from __future__ import annotations

from collections.abc import Callable, Sequence


def retry(operation: Callable[[], int], delays: Sequence[float]) -> int:
    """Retry operation once per delay; return the first successful result.

    Raises:
        ValueError: If ``delays`` is empty.
        RuntimeError: If every attempt fails; the last exception is chained
            as the cause.
    """
    if not delays:
        raise ValueError("delays must contain at least one delay")

    last_error: Exception | None = None
    for delay in delays:
        del delay
        try:
            return operation()
        except Exception as error:
            last_error = error
    raise RuntimeError("retry attempts exhausted") from last_error

