from inventory.models import StockItem


class Inventory:
    """In-memory stock service."""

    def __init__(self) -> None:
        self._items: dict[str, StockItem] = {}

    def add(self, sku: str, quantity: int) -> int:
        """Add ``quantity`` units of ``sku`` and return the new total."""
        if quantity < 0:
            raise ValueError("quantity must not be negative")
        item = self._items.get(sku)
        if item is None:
            item = StockItem(sku=sku, quantity=0)
            self._items[sku] = item
        item.quantity += quantity
        return item.quantity

    def reserve(self, sku: str, quantity: int) -> int:
        """Reserve ``quantity`` units of ``sku`` and return the remaining stock."""
        item = self._items.get(sku)
        if item is None:
            raise KeyError(sku)
        if quantity < 0:
            raise ValueError("quantity must not be negative")
        if quantity > item.quantity:
            raise ValueError("insufficient stock")
        item.quantity -= quantity
        return item.quantity

    def available(self, sku: str) -> int:
        """Return the available stock for ``sku`` (0 when unknown)."""
        item = self._items.get(sku)
        if item is None:
            return 0
        return item.quantity

