from __future__ import annotations

from collections.abc import Sequence


def _lcs_table(old: Sequence[str], new: Sequence[str]) -> list[list[int]]:
    """Return the bounded dynamic-programming LCS length table.

    ``table[i][j]`` is the length of the longest common subsequence of
    ``old[i:]`` and ``new[j:]``.
    """
    n, m = len(old), len(new)
    table = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row = table[i]
        next_row = table[i + 1]
        old_line = old[i]
        for j in range(m - 1, -1, -1):
            if old_line == new[j]:
                row[j] = next_row[j + 1] + 1
            else:
                row[j] = next_row[j] if next_row[j] >= row[j + 1] else row[j + 1]
    return table


def _diff_ops(old: Sequence[str], new: Sequence[str]) -> list[tuple[str, str]]:
    """Return the ordered edit script as ``(tag, line)`` pairs.

    ``tag`` is ``' '`` for a common line, ``'-'`` for a removal and ``'+'``
    for an addition.
    """
    table = _lcs_table(old, new)
    ops: list[tuple[str, str]] = []
    i = j = 0
    n, m = len(old), len(new)
    while i < n and j < m:
        if old[i] == new[j]:
            ops.append((" ", old[i]))
            i += 1
            j += 1
        elif table[i + 1][j] >= table[i][j + 1]:
            ops.append(("-", old[i]))
            i += 1
        else:
            ops.append(("+", new[j]))
            j += 1
    while i < n:
        ops.append(("-", old[i]))
        i += 1
    while j < m:
        ops.append(("+", new[j]))
        j += 1
    return ops


def unified_diff_lines(
    old: Sequence[str],
    new: Sequence[str],
    *,
    context: int = 1,
) -> list[str]:
    """Return a minimal unified-style line diff without trailing newline markers."""
    if context < 0:
        raise ValueError("context must be non-negative")

    ops = _diff_ops(old, new)
    if all(tag == " " for tag, _ in ops):
        return []

    # Indices of changed operations.
    changed = [idx for idx, (tag, _) in enumerate(ops) if tag != " "]
    if not changed:
        return []

    # Merge change regions that are separated by at most 2 * context
    # unchanged lines, then keep at most ``context`` context lines around
    # each merged region.
    keep: list[bool] = [False] * len(ops)
    start = max(0, changed[0] - context)
    end = min(len(ops) - 1, changed[0] + context)
    for idx in changed[1:]:
        if idx - context <= end + 1:
            end = min(len(ops) - 1, idx + context)
        else:
            for k in range(start, end + 1):
                keep[k] = True
            start = max(0, idx - context)
            end = min(len(ops) - 1, idx + context)
    for k in range(start, end + 1):
        keep[k] = True

    return [tag + line for (tag, line), kept in zip(ops, keep) if kept]

