        j += 1
    return script


def unified_diff_lines(
    old: Sequence[str],
    new: Sequence[str],
    *,
    context: int = 1,
) -> list[str]:
    """Return a minimal unified-style line diff without trailing newline markers."""
    if context < 0:
        raise ValueError("context must be non-negative")

    script = _edit_script(old, new)
    if all(tag == " " for tag, _ in script):
        return []

    # Indices of changed entries in the edit script.
    changed = [idx for idx, (tag, _) in enumerate(script) if tag != " "]
    if not changed:
        return []

    # Merge change regions that are separated by at most 2 * context
    # unchanged lines, then emit each region with its surrounding context.
    regions: list[list[int]] = []
    start = max(0, changed[0] - context)
    end = min(len(script) - 1, changed[0] + context)
    for idx in changed[1:]:
        lo = max(0, idx - context)
        hi = min(len(script) - 1, idx + context)
        if lo <= end + 1:
            end = max(end, hi)
        else:
            regions.append([start, end])
            start, end = lo, hi
    regions.append([start, end])

    result: list[str] = []
    for lo, hi in regions:
        for tag, line in script[lo : hi + 1]:
            result.append(tag + line)
    return result

